    print: { d: 'Schreibt Werte in die **Konsole** unter dem Code. Mehrere Werte werden mit Leerzeichen getrennt; Texte erscheinen ohne Anführungszeichen, Spielobjekte als `<Art at x, y>`. Die Konsole behält die letzten 300 Zeilen. `print()` erscheint nur dort, nicht als Meldung im Spiel – dafür gibt es `notify()`.', p: [['*values', 'beliebig', 'auszugebende Werte'], ['sep', 'Text', 'Trenner zwischen den Werten (Standard " ")'], ['end', 'Text', 'Abschluss (Standard Zeilenumbruch)']], r: 'None' },
    notify: { d: '**Meldung senden:** zeigt den Text als Meldung im Spiel (oben am Bildschirm wie andere Spielmeldungen, aber mit dem niedrigsten Vorrang), nicht in der Konsole. Andere Werte als Text werden wie bei `print` umgewandelt. Es gibt höchstens eine solche Meldung: Eine neue ersetzt den Text und zählt mit („… (12 Meldungen)“), eine Schleife flutet den Bildschirm also nicht. Das Programm wartet nicht. Anders als `message()` (nur Missionsskripte) landet der Text nicht im Dialogfenster.', p: [['text', 'beliebig', 'Text der Meldung (höchstens 300 Zeichen)']], r: 'None' },
    // ---------- Held ----------
    nelia: { d: 'Jeder Held ist unter seinem Namen bekannt: `nelia`, `orrin`, `taran`, `malvor` – zuerst dein eigener, sonst der eines anderen Spielers, den du gerade siehst, sonst None. `hero` ist dein erster Held (für ältere Level). Helden sind Spielobjekte der Klasse Hero (siehe „Spielobjekte“).', p: [], r: 'Hero oder None' },
    'nelia.step': { d: 'Geht `n` Kacheln geradeaus **in Blickrichtung** und wartet, bis die Figur angekommen ist. Die Blickrichtung ändert sich dabei nicht. Steht etwas im Weg (Baum, Wasser, Felsen, Kartenrand, Gebäude), gibt es einen Fehler – prüfe vorher mit `can_step()` oder `front()`. Auf Eis, Brücken, Talern, Blumen und Spuren kann man laufen. Gilt auch für Leibeigene und Trupps.', p: [['n', 'Ganzzahl', 'Anzahl der Schritte (Standard 1)']], r: 'None' },
