    'nelia.is_at': { d: 'Prüft, ob die Figur am Ziel steht. Bei einem Ort mit Radius zählt der ganze Kreis, bei einem Punkt genau die Kachel. Geht bei allen Figuren, auch bei fremden, die du siehst.', p: [['target', TARGET, 'Ort, Spielobjekt, (x, y) oder Ortsname']], r: 'True oder False' },
    'nelia.take': { d: 'Hebt auf, was auf der **eigenen** Kachel liegt: Ein Taler kommt als Gold ins Lager, eine Blume wird gepflückt. Dauert 0,5 Sekunden. Liegt nichts da, gibt es einen Fehler – prüfe vorher mit `here()`. Helden und Leibeigene können aufheben, Trupps nicht.', p: [], r: '"coin" oder "flower"' },
    'nelia.put': { d: 'Legt einen Taler aus dem Lager auf die eigene Kachel (kostet ein Gold). Auf jeder Kachel hat nur ein Gegenstand Platz. Dauert 0,5 Sekunden.', p: [['kind', 'Text', 'was abgelegt wird – nur "coin"']], r: 'None' },
    'nelia.say': { d: 'Die Figur sagt etwas: Sprechblase über dem Kopf und Eintrag im Dialogfenster. Das Programm wartet kurz (höchstens 3 Sekunden).', p: [['text', 'Text', 'was die Figur sagt']], r: 'None' },
    'nelia.facing': { d: 'Die Blickrichtung der Figur – in diese Richtung gehen `step()` und `front()`, `left()`/`right()` liegen links und rechts davon. Zu Beginn schaut eine Figur nach Osten.', p: [], r: '"north", "east", "south" oder "west"' },
    'nelia.x': { d: 'Die Kachel, auf der die Figur steht: `x` ist die Spalte (nach rechts größer), `y` die Zeile (nach unten größer). Mit dem Raster im Code-Panel lassen sich die Kacheln abzählen.', p: [], r: 'Ganzzahlen' },
